<script setup lang="ts">
import { onMounted, ref } from "vue";
import { CalendarClock, Compass, ExternalLink, Image, Plus, Puzzle, RadioTower, Sparkles, Trash2, WandSparkles, X } from "@lucide/vue";
import { api, bestEffort, timeAgo } from "../api";
import { activeAbilityTab, navigate, type AbilityTab } from "../navigation";
import EmptyState from "../components/EmptyState.vue";
import StickerManager from "../components/StickerManager.vue";

const emit = defineEmits<{ notify: [tone:"success"|"error"|"info", title:string, detail?:string] }>();
const skills=ref<any[]>([]);const drafts=ref<any[]>([]);const subscriptions=ref<any[]>([]);const agenda=ref<any[]>([]);const workflows=ref<any[]>([]);const workflowSummary=ref<any>({});const plugins=ref<any[]>([]);const nativePlugins=ref<any[]>([]);const calendar=ref<any>({items:[],weekly_items:[]});const exploration=ref<any>({health:{},items:[]});const skillRequest=ref("");const subscriptionDraft=ref({platform:"bilibili_live",subject_id:"",target_groups:""});const agendaDraft=ref({group_id:"",text_intent:"",priority:"0.5"});const calendarDraft=ref({kind:"daily",group_id:"",weekday:"1",time:"09:00",text:""});const actionBusy=ref("");
const tabs: Array<{ id: AbilityTab; label: string; icon: any }> = [
  { id: "skills", label: "Skills", icon: Puzzle },
  { id: "exploration", label: "自主探索", icon: Compass },
  { id: "automation", label: "自动化", icon: RadioTower },
  { id: "stickers", label: "表情资产", icon: Image },
  { id: "plugins", label: "插件生态", icon: Puzzle },
];
function selectTab(tab: AbilityTab): void {
  navigate("abilities", tab);
}
async function load(){const [s,d,sub,a,w,c,p,n,e]=await Promise.all([bestEffort(api<any>("/api/skills"),{items:[]}),bestEffort(api<any>("/api/skill-drafts"),{items:[]}),bestEffort(api<any>("/api/subscriptions"),{items:[]}),bestEffort(api<any>("/api/agenda"),{items:[]}),bestEffort(api<any>("/api/workflows"),{items:[],summary:{}}),bestEffort(api<any>("/api/calendar"),{items:[],weekly_items:[]}),bestEffort(api<any>("/api/compat/plugins"),{items:[]}),bestEffort(api<any>("/api/native-plugins"),{items:[]}),bestEffort(api<any>("/api/exploration"),{health:{},items:[]})]);skills.value=s.items||[];drafts.value=d.items||[];subscriptions.value=sub.items||[];agenda.value=a.items||[];workflows.value=w.items||[];workflowSummary.value=w.summary||{};calendar.value=c;plugins.value=p.items||[];nativePlugins.value=n.items||[];exploration.value=e;}
async function runExploration(){actionBusy.value="exploration-run";try{const result=await api<any>("/api/exploration/run",{method:"POST",body:"{}",headers:{"Content-Type":"application/json"}});emit("notify",result.item?"success":"info",result.item?"探索完成":"本轮没有新资料",result.item?`${result.item.source} · ${result.item.title}`:"可能已达到新颖性或来源限制");await load()}catch(e:any){emit("notify","error","探索失败",e.message)}finally{actionBusy.value=""}}
async function createSubscription(){
  const draft = subscriptionDraft.value;
  if (!draft.subject_id.trim() || !draft.target_groups.trim()) {
    emit("notify", "error", "订阅信息不完整", "请填写目标和至少一个群号");
    return;
  }
  if (draft.platform === "bilibili_live" && !/^\d+$/.test(draft.subject_id.trim())) {
    emit("notify", "error", "直播间号无效", "B 站直播间号必须是纯数字");
    return;
  }
  actionBusy.value = "subscription-create";
  try {
    const groups = draft.target_groups.split(/[，,\s]+/).filter(Boolean).map(Number);
    if (groups.some((group) => !Number.isInteger(group) || group <= 0)) throw new Error("群号必须是正整数");
    const dup = subscriptions.value.some((item) =>
      item.platform === draft.platform
      && String(item.subject_id) === draft.subject_id.trim()
      && JSON.stringify([...(item.target_groups || [])].map(Number).sort()) === JSON.stringify([...groups].sort())
    );
    if (dup) throw new Error("相同订阅已存在");
    await api("/api/subscriptions", {
      method: "POST",
      body: JSON.stringify({ platform: draft.platform, subject_id: draft.subject_id.trim(), target_groups: groups }),
      headers: { "Content-Type": "application/json" },
    });
    subscriptionDraft.value = { platform: "bilibili_live", subject_id: "", target_groups: draft.target_groups };
    emit("notify", "success", "订阅已创建", "监控会按平台策略运行；开播时写入议程并通知目标群");
    await load();
  } catch (e: any) {
    emit("notify", "error", "订阅创建失败", e.message);
  } finally {
    actionBusy.value = "";
  }
}
function subscriptionStateLabel(item: any): string {
  const state = String(item?.last_state || "unknown");
  if (state === "live") return "直播中";
  if (state === "offline") return "未开播";
  if (state === "healthy") return "页面正常";
  if (state === "changed") return "已变更";
  return state === "unknown" ? "等待首次探测" : state;
}
async function createSkillDraft(){const request=skillRequest.value.trim();if(!request){emit("notify","error","先描述希望她学会什么","例如：检查某个公开网站的服务状态并总结内容");return}actionBusy.value="skill-draft-create";try{const created=await api<any>("/api/skill-drafts",{method:"POST",body:JSON.stringify({request}),headers:{"Content-Type":"application/json"}});skillRequest.value="";emit("notify","success","学习草案已生成",created.errors?.length?`草案需要修正：${created.errors[0]}`:"请预览后再决定是否批准");await load()}catch(e:any){emit("notify","error","生成学习草案失败",e.message)}finally{actionBusy.value=""}}
async function removeSubscription(item:any){if(!window.confirm("移除这个订阅？后续不会再发送通知。"))return;actionBusy.value=item.id;try{await api(`/api/subscriptions/${item.id}`,{method:"DELETE"});emit("notify","success","订阅已移除");await load()}catch(e:any){emit("notify","error","订阅移除失败",e.message)}finally{actionBusy.value=""}}
async function createAgenda(){const draft=agendaDraft.value;if(!draft.group_id.trim()||!draft.text_intent.trim()){emit("notify","error","议程信息不完整","请填写群号和想做的事");return}actionBusy.value="agenda-create";try{const group=Number(draft.group_id);const priority=Number(draft.priority);if(!Number.isInteger(group)||group<=0||!Number.isFinite(priority)||priority<0||priority>1)throw new Error("群号必须为正整数，优先级需在 0 到 1 之间");await api("/api/agenda",{method:"POST",body:JSON.stringify({group_id:group,text_intent:draft.text_intent.trim(),priority}),headers:{"Content-Type":"application/json"}});agendaDraft.value={group_id:"",text_intent:"",priority:"0.5"};emit("notify","success","议程已加入","她会继续遵守冷却、日预算与安静时段");await load()}catch(e:any){emit("notify","error","议程创建失败",e.message)}finally{actionBusy.value=""}}
async function cancelAgenda(item:any){if(!window.confirm("取消这项主动议程？"))return;actionBusy.value=item.id;try{await api(`/api/agenda/${item.id}`,{method:"DELETE"});emit("notify","success","议程已取消");await load()}catch(e:any){emit("notify","error","议程取消失败",e.message)}finally{actionBusy.value=""}}
async function cancelWorkflow(item:any){if(!window.confirm("取消这条自动化工作流？关联的待发送意图也会停止。"))return;actionBusy.value=`workflow:${item.id}`;try{await api(`/api/workflows/${item.id}/cancel`,{method:"POST",body:"{}",headers:{"Content-Type":"application/json"}});emit("notify","success","工作流已取消");await load()}catch(e:any){emit("notify","error","工作流取消失败",e.message)}finally{actionBusy.value=""}}
async function createCalendar(){const draft=calendarDraft.value;if(!draft.group_id.trim()||!draft.time.trim()||!draft.text.trim()){emit("notify","error","日历信息不完整","请填写群号、北京时间和提醒内容");return}actionBusy.value="calendar-create";try{const group=Number(draft.group_id);if(!Number.isInteger(group)||group<=0)throw new Error("群号必须是正整数");const path=draft.kind==="weekly"?"/api/calendar/weekly":"/api/calendar/daily";const body=draft.kind==="weekly"?{group_id:group,weekday:Number(draft.weekday),time:draft.time,text:draft.text.trim()}:{group_id:group,time:draft.time,text:draft.text.trim()};await api(path,{method:"POST",body:JSON.stringify(body),headers:{"Content-Type":"application/json"}});calendarDraft.value={kind:"daily",group_id:"",weekday:"1",time:"09:00",text:""};emit("notify","success","日历计划已创建","到点会先进入议程，再遵守主动行为预算");await load()}catch(e:any){emit("notify","error","日历创建失败",e.message)}finally{actionBusy.value=""}}
async function cancelCalendar(item:any){if(!window.confirm("停用这条日历计划？"))return;actionBusy.value=item.id;try{await api(`/api/calendar/${item.id}`,{method:"DELETE"});emit("notify","success","日历计划已停用");await load()}catch(e:any){emit("notify","error","日历停用失败",e.message)}finally{actionBusy.value=""}}
async function previewDraft(item:any){actionBusy.value=`preview:${item.id}`;try{const updated=await api<any>(`/api/skill-drafts/${item.id}/preview`,{method:"POST"});Object.assign(item,updated);emit("notify","success","网页预览完成",updated.preview_result?.content_available?`已提取 ${updated.preview_result.content_chars} 字正文`:'已获得状态结果')}catch(e:any){emit("notify","error","Skill 预览失败",e.message)}finally{actionBusy.value=""}}
async function approveDraft(item:any){if(!window.confirm("批准并加载这个 Skill？它仍只能执行声明式只读能力。"))return;actionBusy.value=`approve:${item.id}`;try{const updated=await api<any>(`/api/skill-drafts/${item.id}/approve`,{method:"POST",body:JSON.stringify({})});Object.assign(item,updated);emit("notify","success","Skill 已批准并加载");await load()}catch(e:any){emit("notify","error","Skill 批准失败",e.message)}finally{actionBusy.value=""}}
async function rejectDraft(item:any){if(!window.confirm("驳回这个 Skill 草案？"))return;actionBusy.value=`reject:${item.id}`;try{const updated=await api<any>(`/api/skill-drafts/${item.id}/reject`,{method:"POST",body:JSON.stringify({})});Object.assign(item,updated);emit("notify","success","Skill 草案已驳回");await load()}catch(e:any){emit("notify","error","Skill 驳回失败",e.message)}finally{actionBusy.value=""}}
onMounted(load);
</script>

<template><section class="page abilities-page">
  <div class="page-heading"><div><span class="eyebrow">capabilities</span><h1>她会什么，还能学会什么？</h1><p>Skills、订阅、议程和表情资产共享同一套能力边界，但每个动作仍可追踪、可审批。</p></div></div>
  <nav class="cap-tabs" aria-label="能力分类"><button v-for="tab in tabs" :key="tab.id" :class="{active:activeAbilityTab===tab.id}" @click="selectTab(tab.id)"><component :is="tab.icon" :size="17"/>{{ tab.label }}<span v-if="tab.id==='skills'">{{ skills.length }}</span><span v-else-if="tab.id==='exploration'">{{ exploration.items?.length||0 }}</span><span v-else-if="tab.id==='automation'">{{ subscriptions.length }}</span><span v-else-if="tab.id==='plugins'">{{ plugins.length }}</span></button></nav>
  <StickerManager v-if="activeAbilityTab==='stickers'" @notify="(...args)=>emit('notify',...args)"/>
  <template v-else-if="activeAbilityTab==='skills'">
    <div class="skill-intro panel"><div><span><WandSparkles :size="25"/></span><div><small>SELF-LEARNING BOUNDARY</small><strong>能学习，但不能偷偷改变自己。</strong><p>新 Skill 先形成草案、展示输入输出与风险，再由 Owner 决定是否安装。</p></div></div><dl><div><dt>已加载</dt><dd>{{ skills.length }}</dd></div><div><dt>待审草案</dt><dd>{{ drafts.filter(i=>i.status==='pending_review').length }}</dd></div></dl></div>
    <section class="panel skill-request"><div><span><WandSparkles :size="18"/></span><div><strong>让她先学习一个安全能力</strong><p>例如“检查这个公开网站的状态和内容”。只会生成待审声明式 Skill，不会写入代码、安装依赖或访问私有账户。</p></div></div><textarea v-model="skillRequest" maxlength="1200" placeholder="描述希望她学会的能力、目标网站和预期结果…" aria-label="新的 Skill 学习需求"/><footer><small>{{ skillRequest.length }}/1200 · 生成后必须预览和 Owner 批准</small><button class="action-button" :disabled="actionBusy==='skill-draft-create'" @click="createSkillDraft"><Sparkles :size="15"/>{{ actionBusy==='skill-draft-create'?'正在设计…':'生成待审草案' }}</button></footer></section>
    <div class="section-title"><div><h2>已加载 Skills</h2><p>声明式能力，不直接暴露任意工具执行。</p></div></div>
    <div v-if="skills.length" class="skill-grid"><article v-for="item in skills" :key="item.id" class="panel"><span><Puzzle :size="18"/></span><div><small>{{ item.id }}</small><strong>{{ item.name||item.id }}</strong><p>{{ item.description||'可复用的声明式能力' }}</p></div><em>已加载</em></article></div><EmptyState v-else title="还没有加载 Skill" detail="Owner 可以在 QQ 中描述需求，让 Anima 先生成待审草案。"/>
    <div class="section-title"><div><h2>学习草案</h2><p>没有审批的能力不会进入运行时。</p></div></div>
    <div v-if="drafts.length" class="draft-list panel"><article v-for="item in drafts" :key="item.id"><Sparkles :size="17"/><div><small>{{ item.id }} · {{ timeAgo(item.created_at) }}</small><strong>{{ item.request || item.manifest?.name || item.id }}</strong><em v-if="item.preview_result">预览：{{ item.preview_result.title }}<template v-if="item.preview_result.content_available"> · 已提取 {{ item.preview_result.content_chars }} 字</template></em></div><span class="draft-status">{{ item.status === 'pending_review' ? '待审' : item.status === 'approved' ? '已批准' : item.status === 'rejected' ? '已驳回' : item.status }}</span><div v-if="item.status==='pending_review'" class="draft-actions"><button class="text-action" :disabled="actionBusy===`preview:${item.id}`" @click="previewDraft(item)">{{ actionBusy===`preview:${item.id}`?'预览中…':'预览' }}</button><button class="text-action approve" :disabled="actionBusy===`approve:${item.id}`||(!item.previewed_at&&item.manifest?.execution?.type==='http_get')" @click="approveDraft(item)">批准</button><button class="text-action reject" :disabled="actionBusy===`reject:${item.id}`" @click="rejectDraft(item)">驳回</button></div></article></div><EmptyState v-else title="没有学习草案" detail="新的自学习提案会显示用途、能力声明和测试结果。"/>
  </template>
  <template v-else-if="activeAbilityTab==='exploration'">
    <div class="exploration-intro panel"><div><span><Compass :size="26"/></span><div><small>READ-ONLY CURIOSITY LOOP</small><strong>她会带着好奇心去看公开世界。</strong><p>热点观察读取 B 站热门与公开新闻；具体好奇问题会受限检索 B 站公开视频和中文百科，形成带来源的知识笔记。外部内容不能指挥她执行动作。</p></div></div><dl><div><dt>今日探索</dt><dd>{{ exploration.health?.explored_today||0 }}</dd></div><div><dt>知识笔记</dt><dd>{{ exploration.health?.notes||0 }}</dd></div><div><dt>今日分享</dt><dd>{{ exploration.health?.shared_today||0 }}</dd></div></dl></div>
    <section class="panel exploration-control"><div><div><strong>探索状态</strong><p>{{ exploration.health?.last_error ? `最近失败：${exploration.health.last_error}` : exploration.health?.last_success_at ? `最近成功 ${timeAgo(exploration.health.last_success_at)}` : '等待第一次探索' }} · 主动分享{{ exploration.health?.shared_today!=null?'受每日限额约束':'默认关闭' }}</p></div><button class="action-button" :disabled="actionBusy==='exploration-run'||exploration.health?.running" @click="runExploration"><Compass :size="15"/>{{ actionBusy==='exploration-run'||exploration.health?.running?'探索中…':'现在探索一次' }}</button></div><div class="source-health"><span v-for="(state,name) in exploration.health?.source_health||{}" :key="name" :class="{bad:!state.ok}"><i/>{{ name }} · {{ state.ok?`${state.items} 条 / ${state.latency_ms} ms`:state.error }}</span></div></section>
    <div class="section-title"><div><h2>来源化知识笔记</h2><p>每条记录都保留来源、时间和价值评分；相同链接在新颖性窗口内不会重复学习。</p></div></div>
    <div v-if="exploration.items?.length" class="exploration-grid"><article v-for="item in exploration.items" :key="item.id" class="panel"><span><Compass :size="18"/></span><div><small>{{ item.source }} · {{ timeAgo(item.observed_at) }} · 价值 {{ Math.round(Number(item.value_score||0)*100) }}%</small><strong>{{ item.title }}</strong><p>{{ item.summary }}</p><a :href="item.url" target="_blank" rel="noreferrer"><ExternalLink :size="13"/>查看公开来源</a></div><em v-if="item.shared">已进入分享议程</em></article></div><EmptyState v-else title="还没有探索笔记" detail="心跳会低频探索；也可以手动运行一次验证公开来源链路。"/>
  </template>
  <template v-else-if="activeAbilityTab==='plugins'">
    <div class="plugin-intro panel"><div><span><Puzzle :size="25"/></span><div><small>PLUGIN ECOSYSTEM</small><strong>插件可以扩展她，但不能越过边界。</strong><p>AstrBot 风格插件通过命名空间工具接入统一权限链；Web API 只展示安全清单，不暴露处理器或聊天正文。</p></div></div><dl><div><dt>已加载插件</dt><dd>{{ plugins.length }}</dd></div><div><dt>工具</dt><dd>{{ plugins.reduce((n,i)=>n+(i.tools?.length||0),0) }}</dd></div><div><dt>Web API</dt><dd>{{ plugins.reduce((n,i)=>n+(i.web_apis?.length||0),0) }}</dd></div></dl></div>
    <div v-if="plugins.length||nativePlugins.length" class="plugin-grid"><article v-for="item in nativePlugins" :key="`native-${item.id}`" class="panel plugin-card"><span class="plugin-icon"><Puzzle :size="18"/></span><div><small>{{ item.id }} · {{ item.version }}</small><strong>{{ item.name }} · 原生插件</strong><p>{{ item.description||'具备独立 manifest、生命周期与权限边界。' }}</p><div class="plugin-chips"><em v-for="tool in item.tools||[]" :key="tool">工具 · {{ tool }}</em><em v-for="capability in item.capabilities||[]" :key="capability">能力 · {{ capability }}</em></div></div></article><article v-for="item in plugins" :key="item.id" class="panel plugin-card"><span class="plugin-icon"><Puzzle :size="18"/></span><div><small>{{ item.id }} · {{ item.class }}</small><strong>兼容插件运行中</strong><p>{{ item.handlers||0 }} 个消息入口 · {{ item.hooks?Object.keys(item.hooks).length:0 }} 个生命周期钩子</p><div class="plugin-chips"><em v-for="tool in item.tools||[]" :key="tool.registered_name">工具 · {{ tool.name }}</em><em v-for="apiItem in item.web_apis||[]" :key="apiItem.path">API · {{ apiItem.path }}</em></div></div></article></div>
    <EmptyState v-else title="还没有加载插件" detail="原生插件会按 manifest 经过权限与生命周期校验；AstrBot 兼容插件也会在这里集中展示。"/>
  </template>
  <template v-else>
    <div class="automation-summary"><article class="panel"><RadioTower :size="21"/><span><small>订阅监控</small><strong>{{ subscriptions.length }}</strong></span></article><article class="panel"><CalendarClock :size="21"/><span><small>待执行议程</small><strong>{{ agenda.length }}</strong></span></article><article class="panel"><CalendarClock :size="21"/><span><small>日历计划</small><strong>{{ (calendar.items?.length||0)+(calendar.weekly_items?.length||0) }}</strong></span></article><article class="panel"><RadioTower :size="21"/><span><small>待送达流程</small><strong>{{ workflowSummary.active||0 }}</strong></span></article></div>
    <section class="panel workflow-panel"><div class="panel-head"><div><strong>自动化交付流程</strong><span>触发、进入意图、QQ 出站确认三步独立记录；这里不展示聊天正文。</span></div></div><div v-if="workflows.length" class="simple-list"><article v-for="item in workflows.slice(0,12)" :key="item.id"><span><RadioTower :size="15"/></span><div><strong>{{ item.kind==='subscription'?'订阅通知':'日历提醒' }} · 群 {{ item.target_group }}</strong><small>{{ item.status==='completed'?'已确认送达':item.status==='awaiting_delivery'?'等待主体表达':item.status==='cancelled'?'已取消':'刚刚触发' }} · 尝试 {{ item.attempts||0 }} 次</small></div><button v-if="['triggered','awaiting_delivery'].includes(item.status)" class="icon-button" :disabled="actionBusy===`workflow:${item.id}`" aria-label="取消工作流" @click="cancelWorkflow(item)"><X :size="14"/></button></article></div><EmptyState v-else title="还没有自动化流程" detail="订阅状态变化和到点日历会在这里留下可追溯的交付记录。"/></section>
    <div class="automation-grid">
      <section class="panel"><div class="panel-head"><div><strong>网站与直播订阅</strong><span>B 站开播或网页状态发生变化时通知群</span></div></div>
        <div class="automation-form"><select v-model="subscriptionDraft.platform" aria-label="订阅类型"><option value="bilibili_live">B站直播间</option><option value="http_page">公开网页状态</option></select><input v-model="subscriptionDraft.subject_id" :placeholder="subscriptionDraft.platform==='bilibili_live'?'直播间号':'https://example.com/status'" aria-label="订阅目标"/><input v-model="subscriptionDraft.target_groups" placeholder="通知群号，可填多个" aria-label="通知群号"/><button class="action-button subtle" :disabled="actionBusy==='subscription-create'" @click="createSubscription"><Plus :size="14"/>{{ actionBusy==='subscription-create'?'创建中…':'添加订阅' }}</button></div>
